package xt2png

import (
	"encoding/hex"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestPreflateSynthetic(t *testing.T) {
	for _, tc := range []struct{ name, raw, diff, out string }{
		{"stored", "73746f7265642d626c6f636b2d706c61696e2d746578742121", "8c48108e16009804", "011900e6ff73746f7265642d626c6f636b2d706c61696e2d746578742121"},
		{"hello1", "68656c6c6f20707265666c617465", "8c48108e0304", "cb48cdc9c95728284a4dcb492c490500"},
		{"gohello_m2", "68656c6c6f20707265666c6174652066726f6d20676f20666c617465", "8c48188ea239007026", "001c00e3ff68656c6c6f20707265666c6174652066726f6d20676f20666c6174650300"},
		{"rep1", "", "8cd0138e0304", "4b4c4a4e1c45c3370400"},
	} {
		raw, err := hex.DecodeString(tc.raw)
		require.NoError(t, err)
		diff, err := hex.DecodeString(tc.diff)
		require.NoError(t, err)
		want, err := hex.DecodeString(tc.out)
		require.NoError(t, err)
		got, err := preflate(raw, diff, len(want))
		require.NoError(t, err, tc.name)
		require.Equal(t, want, got, tc.name)
		_, err = preflate(raw, diff, 1)
		require.EqualError(t, err, "xt2png: guest: preflate -2")
		got, err = preflate(raw, diff, 0)
		require.NoError(t, err, tc.name)
		require.Equal(t, want, got, tc.name)
	}
	_, err := preflate([]byte{1, 2, 3}, nil, 32)
	require.EqualError(t, err, "xt2png: guest: preflate -1")
}
